// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recording/** * NOUS — Recording Services (Module 11 v3 — Step 11.5). * * Service interfaces for call recording + transcription + encrypted storage. * All on-device, privacy-first. */// ──────────────────────────────────────────────────────────────────────────// Audio Recorder (wraps MediaRecorder / AudioRecord)// ──────────────────────────────────────────────────────────────────────────/** * Interface for recording call audio. * * Real implementation ([AndroidAudioRecorder]) uses AudioRecord with * VOICE_CALL source (requires CAPTURE_AUDIO_OUTPUT permission on Android 10+, * or AccessibilityService bypass for Android 9+). * * Tests inject a fake. */interface AudioRecorder {    /** Start recording call audio. Returns true if recording started. */    fun startRecording(): Boolean    /** Stop recording. Returns the raw audio data. */    fun stopRecording(): ByteArray?    /** True if currently recording. */    fun isRecording(): Boolean    /** Get the current recording duration in seconds. */    fun getDurationSeconds(): Long}// ──────────────────────────────────────────────────────────────────────────// Transcription LLM (wraps Module 4 local LLM)// ──────────────────────────────────────────────────────────────────────────/** * Interface for transcribing audio to text via local LLM. * * Real implementation uses Module 4's Whisper.cpp (Step 5.4) for STT. * Tests inject a fake. */interface TranscriptionLlm {    /**     * Transcribe [audioData] to text.     *     * @param audioData raw PCM audio (16 kHz, 16-bit mono).     * @return transcribed text, or null if transcription failed.     */    suspend fun transcribe(audioData: ByteArray): String?    /** True if the transcription model is loaded and ready. */    fun isReady(): Boolean}// ──────────────────────────────────────────────────────────────────────────// Recording Store (encrypted local storage)// ──────────────────────────────────────────────────────────────────────────/** * Interface for storing encrypted call recordings + transcripts. * * Real implementation uses Room (encrypted with SQLCipher from Module 3). * Tests inject an in-memory fake. * * ## Privacy * *  - Recordings are AES-256 encrypted before storage. *  - Transcripts are stored in encrypted Memory (Module 3). *  - User can delete recordings anytime. *  - Never synced to cloud. */interface RecordingStore {    /** Store an encrypted recording + transcript. */    suspend fun store(recording: CallRecording): String    /** Get a recording by ID. */    suspend fun get(recordingId: String): CallRecording?    /** Search recordings by transcript content. */    suspend fun searchByTranscript(query: String, limit: Int = 10): List<CallRecording>    /** Get recent recordings. */    suspend fun getRecent(limit: Int = 20): List<CallRecording>    /** Delete a recording. */    suspend fun delete(recordingId: String): Boolean    /** Delete all recordings. */    suspend fun deleteAll(): Int    /** Count of stored recordings. */    suspend fun count(): Int}// ──────────────────────────────────────────────────────────────────────────/** * One call recording (encrypted audio + transcript + metadata). * * @param id unique recording ID. * @param contactName display name of the other party (or "Unknown"). * @param phoneNumber phone number of the other party. * @param timestampMs when the call occurred. * @param durationSeconds call duration. * @param encryptedAudioPath path to the AES-256 encrypted audio file. * @param transcript transcribed text (null if not yet transcribed). * @param isTranscribed true if transcription is complete. */data class CallRecording(    val id: String,    val contactName: String,    val phoneNumber: String,    val timestampMs: Long,    val durationSeconds: Long,    val encryptedAudioPath: String,    val transcript: String? = null,    val isTranscribed: Boolean = false,) {    init {        require(id.isNotBlank()) { "Recording id must not be blank" }        require(contactName.isNotBlank()) { "Contact name must not be blank" }        require(phoneNumber.isNotBlank()) { "Phone number must not be blank" }        require(durationSeconds >= 0) { "Duration must be non-negative" }    }}